/** Every failure one corpus vector states against this frontend. */
export function runVector(vectorId: string): string[] {
  const vector = VECTORS[vectorId];
  if (vector === undefined) {
    throw new Error(`unknown conformance vector '${vectorId}'`);
  }
  return vector();
}

/** Every failure the whole corpus states against this frontend. */
export function runConformance(): string[] {
  return VECTOR_IDS.flatMap((vectorId) => runVector(vectorId));
}

